-- Explicit fork scopes: Plans belongs to a ministry group; manual Tasks belongs
-- to its assigned group. Deleting/reclassifying a scope cannot revive old grants.
CREATE TRIGGER revoke_deleted_doing_scopes AFTER DELETE ON groups BEGIN DELETE FROM role_permissions WHERE churchId=OLD.churchId AND apiName='DoingApi' AND contentType IN ('Plans','Tasks') AND contentId=OLD.id; END;
CREATE TRIGGER revoke_changed_ministry_scope AFTER UPDATE OF tags ON groups WHEN instr(','||NEW.tags||',',',ministry,')=0 BEGIN DELETE FROM role_permissions WHERE churchId=NEW.churchId AND apiName='DoingApi' AND contentType='Plans' AND contentId=NEW.id; END;
CREATE TRIGGER doing_plan_type_ministry_update BEFORE UPDATE OF ministryId ON doing_plan_types WHEN NEW.ministryId<>OLD.ministryId AND EXISTS(SELECT 1 FROM doing_plans p WHERE p.churchId=NEW.churchId AND p.planTypeId=NEW.id AND p.ministryId<>NEW.ministryId) BEGIN SELECT RAISE(ABORT,'CHECK constraint failed: plan_type_ministry'); END;
CREATE TRIGGER doing_plan_ministry_insert BEFORE INSERT ON doing_plans WHEN NEW.planTypeId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM doing_plan_types pt WHERE pt.churchId=NEW.churchId AND pt.id=NEW.planTypeId AND pt.ministryId=NEW.ministryId) BEGIN SELECT RAISE(ABORT,'CHECK constraint failed: plan_type_ministry'); END;
CREATE TRIGGER doing_plan_ministry_update BEFORE UPDATE OF ministryId,planTypeId ON doing_plans WHEN NEW.planTypeId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM doing_plan_types pt WHERE pt.churchId=NEW.churchId AND pt.id=NEW.planTypeId AND pt.ministryId=NEW.ministryId) BEGIN SELECT RAISE(ABORT,'CHECK constraint failed: plan_type_ministry'); END;
